package payer

type account struct {
	id      uuid.UUID
	name    string
	balance int
}

var (
	ErrFromAccNotFound = err
)

// implementation is hidden (sqlx-like)
type AccountRepository interface {
	BeginTx() (AccountRepository, error)
	Find(id uuid.UUID) (*account, error)
	Save(acc *account) error
	SavePayment(t *payment) error
	FindPayments(accId uuid.UUID) ([]payment, error)
	Commit() error
	Rollback() error
}

type TxAccountRepository interface {
}

// implementation sends to some broker, but could also be an http post
type EventSender interface {
	Send(event interface{}) error
}

type payment struct {
	fromId uuid.UUID
	toId   uuid.UUID
	amount int // in kopecks
	at     time.Time
}

type Account_Service struct {
	repository  AccountRepository
	eventSender EventSender
}

// called from the rest controller
func (s Account_Service) CreatePayment(ctx context.Context, fromId uuid.UUID, toId uuid.UUID, amount int) error {
	tx, err := s.repository.BeginTx(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	fromAcc, err := tx.Find(ctx, fromId)
	if err != nil {
		tx.Rollback()
		return errNotFound
	}

	toAcc, err := tx.Find(ctx, toId)
	if err != nil {
		tx.Rollback()
		return err
	}

	if fromAcc.Balance < amount {
		tx.Rollback()
		return errors.New("insufficient")
	}

	fromAcc.Balance -= amount
	toAcc.Balance += amount

	if err := tx.Save(ctx, fromAcc); err != nil {
		tx.Rollback()
		return err
	}

	if err := tx.Save(ctx, toAcc); err != nil {
		tx.Rollback()
		return err
	}

	err = tx.SavePayment(ctx, &payment{
		fromId: fromId,
		toId:   toId,
		amount: amount,
	})
	if err != nil {
		tx.Rollback()
		return err
	}

	if err := tx.SendOutbox(ctx, &payment{
		fromId: fromId,
		toId:   toId,
		amount: amount,
		at:     time.Now().UTC(),
	}); err != nil {
		tx.Rollback()
		return err
	}

	return tx.Commit()
}

// called from the rest controller
func (s *Account_Service) get_payments(ctx context.Context, fromId uuid.UUID, limit, offset int) ([]payment, error) {
	payments, err := s.repository.FindPayments(ctx, fromId, limit, offset)
	if err != nil {
		return nil, err
	}

	return payments, nil
}

a:
The problems:

- **Race / lost update**: it reads balances with plain `Find`, checks and modifies them in Go, and then `Save`s absolute values. Two concurrent transfers from the same account both pass the check, which means a double spend. Fix: lock the rows (`SELECT ... FOR UPDATE`) or use atomic `balance = balance - $x WHERE balance >= $x`.
- **Deadlocks**: A→B and B→A lock in opposite orders. Lock both rows in **one query ordered by id**.
- **No validation**: `amount <= 0`, `from == to`, and currency or overflow are unchecked. Money is an `int`, so document the minor units.
- **Error handling**: explicit `tx.Rollback()` calls duplicate the `defer`. The not-found path drops the original error (`errNotFound`, not wrapped, and undefined). Errors are compared by message (`errors.New` inline). Use sentinel errors plus `%w`.
- **API mismatch**: the interface methods take no `ctx` while the calls pass one. `BeginTx` returns the same repository interface, and there's an empty `TxAccountRepository`. The struct field is `balance`, but the code uses `Balance`. `payment.at` is unset on save.
- **Outbox**: writing the event in the same transaction is the right idea (vs `EventSender.Send`, which would be a dual write). The payload needs an ID for consumer dedup, and a relay must publish it.
- **Style/API**: the value receiver is inconsistent with the pointer receiver, `Account_Service`/`get_payments` aren't Go naming, and `FindPayments` uses `OFFSET` pagination (prefer keyset `ORDER BY created_at DESC, id DESC`) with an index on `(from_id, created_at)`.

Fixed core (checked with `go vet`; SQL run on PG18):

```go
func (s *Service) CreatePayment(ctx context.Context, fromID, toID string, amount int64) error {
	if amount <= 0 || fromID == toID {
		return ErrInvalidTransfer
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin: %w", err)
	}
	defer tx.Rollback()

	rows, err := tx.QueryContext(ctx,
		`SELECT id, balance FROM accounts WHERE id IN ($1, $2) ORDER BY id FOR UPDATE`,
		fromID, toID)
	if err != nil {
		return fmt.Errorf("lock accounts: %w", err)
	}
	balances := make(map[string]int64, 2)
	for rows.Next() {
		var id string
		var b int64
		if err := rows.Scan(&id, &b); err != nil {
			rows.Close()
			return err
		}
		balances[id] = b
	}
	if err := rows.Err(); err != nil {
		return err
	}
	rows.Close()

	from, ok := balances[fromID]
	if !ok {
		return fmt.Errorf("from %s: %w", fromID, ErrAccountNotFound)
	}
	if _, ok := balances[toID]; !ok {
		return fmt.Errorf("to %s: %w", toID, ErrAccountNotFound)
	}
	if from < amount {
		return ErrInsufficientFunds
	}
	if _, err := tx.ExecContext(ctx,
		`UPDATE accounts SET balance = balance - $2 WHERE id = $1`, fromID, amount); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx,
		`UPDATE accounts SET balance = balance + $2 WHERE id = $1`, toID, amount); err != nil {
		return err
	}
	var paymentID string
	if err := tx.QueryRowContext(ctx,
		`INSERT INTO payments (from_id, to_id, amount, created_at)
		 VALUES ($1, $2, $3, now()) RETURNING id`, fromID, toID, amount).Scan(&paymentID); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx,
		`INSERT INTO outbox (topic, key, payload) VALUES ('payments', $1,
		 json_build_object('id', $1::text, 'from', $2::text, 'to', $3::text, 'amount', $4::bigint))`,
		paymentID, fromID, toID, amount); err != nil {
		return err
	}
	return tx.Commit()
}
```

code:
CREATE TABLE t(
    a int NOT NULL,
    b int NOT NULL,
    c int NOT NULL
);

EXPLAIN ANALYZE
SELECT * FROM t WHERE a = 1 AND b = 1 ORDER BY c;

a:
In Postgres the minimum is **Repeatable Read**.

Under **Read Committed** each *statement* takes a fresh snapshot. A concurrent transaction that inserts or deletes rows and commits between the two queries makes the page and the total disagree. For example, the count includes a row the page never showed, or the page shows 20 rows while the count says 19. That's a non-repeatable read / phantom across statements.

Under **Repeatable Read**, Postgres takes one snapshot at the first statement and uses it for the whole transaction. Both queries see exactly the same data, including no phantoms (Postgres RR is stronger than the SQL standard requires). Read-only RR transactions never fail with serialization errors, so this is cheap:

```sql
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT ... ORDER BY id LIMIT 20 OFFSET 40;
SELECT count(*) FROM ...;
COMMIT;
```

Alternatives: compute both in one statement (`count(*) OVER ()` as a window function), or accept approximate totals. Serializable is unnecessary here.

In MySQL/InnoDB, RR also gives a consistent snapshot for plain reads.

